from omission_cycle_enumeration import pair_boxes,triple_table
base=Path('.cache/recovery-residual32/core-next');D=json.loads(Path('.cache/schroeder-release/es7_es8_bounds_81_319_v1/certificates/residual.json').read_text());states=D['states'];cells=[{(x+1,y) for x,h in enumerate(s[:4]) for y in range(1,h+1)} for s in states];P,mn,mx=pair_boxes(states);TT=triple_table(P,mn,mx)
def parity(q):return sum(q[i]>q[j] for i in range(len(q)) for j in range(i+1,len(q)))%2
def validate(S,a,H):
 n=len(S);assert not set(S)&H;pos=a['positions'];assert sorted(pos)==list(range(n));labels={(i,j):(x,y) for i,j,x,y in a['labels']};ori={tuple(q[:3]):q[3] for q in a['orientations']};assert len(labels)==n*(n-1)//2
 def sign(q):return ori[tuple(sorted(q))]^(parity(q)==1)
 order=sorted(range(n),key=lambda i:pos[i])
 for i,j in itertools.combinations(order,2):
  x,y=labels[tuple(sorted((i,j)))];assert 1<=x<=4 and 1<=y<=6 and (x,y)!=(1,6);assert (x,y) in cells[S[j]]-cells[S[i]]
 for i,j,k in itertools.combinations(order,3):
  coordinate=int(sign((i,j,k)));assert labels[tuple(sorted((i,j)))][coordinate]<labels[tuple(sorted((j,k)))][coordinate]
 for q in itertools.combinations(order,4):
  v=[sign(t) for t in itertools.combinations(q,3)];assert sum(a!=b for a,b in zip(v,v[1:]))<=1
 for q,v in ori.items():
  i,j,k=[S[t] for t in q]
  if TT[i,j,k]:assert v
  elif TT[i,k,j]:assert not v
 convex={}
 for i,j,k,l in itertools.combinations(range(n),4):
  x,y,z,w=(ori[t] for t in [(i,j,k),(i,j,l),(i,k,l),(j,k,l)]);convex[i,j,k,l]=sum((not w,z,not y,x))==2
 count=0
 for eight in itertools.combinations(range(n),8):count+=1;assert not all(convex[q] for q in itertools.combinations(eight,4))
 return count

def project(S,a,target):
 ids=[S.index(s) for s in target];n=len(ids);positions=a['positions'];ordered=sorted(ids,key=lambda i:positions[i]);newp=[ordered.index(i) for i in ids];labels={(i,j):(x,y) for i,j,x,y in a['labels']};ori={tuple(q[:3]):q[3] for q in a['orientations']}
 return {'positions':newp,'labels':[[i,j,*labels[tuple(sorted((ids[i],ids[j])))]] for i,j in itertools.combinations(range(n),2)],'orientations':[[*q,ori[tuple(sorted(ids[i] for i in q))]^(parity([ids[i] for i in q])==1)] for q in itertools.combinations(range(n),3)]}

