  for v in S:
   r=deletions[v];path=root/r['assignment'];d=json.loads(path.read_text());target=[s for s in S if s!=v];assert set(target)<=set(d['support']);a=project(d['support'],d['assignment'],target);count=validate(target,a,H);projections.append({'removed':v,'target':target,'source_assignment':str(path),'eight_subsets_checked':count,'assignment':a,'complete':True})
 record={'scope':'Independent exact SAT replay and deletion projection; solver-UNSAT claims still require kernel verification.','witness':str(wp),'witness_sha256':prov['witness_sha256'],'minimal_support':S,'assignment_count':len(reports),'assignments':reports,'all_single_deletions_exactly_replayed':len(projections)==len(S),'deletion_projections':projections}
 (root/'independent-replay.json').write_text(json.dumps(record,indent=2)+'\n');allreports.append({'root':str(root),'assignments':len(reports),'minimal_support':S,'deletions_projected_and_checked':len(projections)})
